REDEN='Rogier: leg alles vast, 2026-10-31'
B=[(1,'Lengte roman blijft ca. 55.000 woorden','Geen opvulling; boek blijft ca. 54.500 woorden (hoofdstukken 54.462 na revisieronde 2). Wattpad beloont strakheid.',-1240,'ROMAN-Z16-roman;BESLUIT-Z20-5'),
(2,'Hesta\'s motief voor de bestanden blijft een hint','Waarom Hesta de bestanden laat schrappen (haar eigen toegangen tot de kern) blijft in dit boek een hint; eventuele onthulling pas in de hoofdserie. H27 geeft wel één regel inlossing (YSA-Z21-16).',-1238,'ROMAN-Z16-h27;BESLUIT-Z15-5;YSA-Z21-16'),
(3,'Corrans vallei is de latere plek van Ves-Anath','De groene vallei in de zuidelijke uitlopers van Hoogvrouwe ("the Lady") waar Corran met zijn vertrekkers heen gaat, is de latere plek van Ves-Anath; in de roman alleen aangeduid, niet benoemd. Daar valt in -480 ook de val neer.',-1238,'ROMAN-Z16-h30;ROMAN-Z16-h33;YSA-Z21-6'),
(4,'Thalens bewaarde stem is een haak naar de hoofdserie','"His was for later": de scherf spreekt met Ysa\'s stem, Thalens ingesproken stem is bewaard voor later en wordt een haak naar de hoofdserie.',-1198,'ROMAN-Z16-h33;YSA-Z21-14'),
(5,'Nieuwe feiten h25-33 en review vastgesteld','Alle nieuwe feiten uit h25-33 (YSA-Z21-1..14) en de review (YSA-Z21-15..19) vastgesteld; het aantal van 211 vertrekkers mag bij latere canon over het bergvolk worden bijgesteld.',-1238,'YSA-Z21-6')]
Y=[(1,'Lander zeven luistert, Hesta laat de deur open','De hullmicrofoon van lander zeven staat open; Hesta laat de deur open voor Thalen (toestemming om mee te luisteren). Het oog van lander vijf bestaat niet meer.',-1238,'h25'),
(2,'Ysa\'s oortje: twee jaar open lijn','Ysa\'s oortje heeft twee jaar een open lijn naar het schip gehad; de Reckoner leest haar hartslag erdoor; Thalen hoort de stemming via dat oortje.',-1238,'h25/h29'),
(3,'Hesta krijgt negen vonkcellen','Hesta krijgt negen vonkcellen onder haar eigen slot, bij regel en op verzoek van de raad: kiem voor latere machinebeheer- of Orde-macht (moet in de hoofdserie vervolg krijgen of uitdoven).',-1238,'h27'),
(4,'Motie om de bestanden te schrappen komt van Hesta','Hesta dient de motie in om de bestanden te schrappen; ze worden eerst geschrapt en blijven ongelezen in de kern.',-1238,'h27/h29'),
(5,'Tobin en Aster; Ysa niet in de grondraad; berkenbast','De raadsleden voor hydroponics heten Tobin en Aster. Ysa zit niet in de grondraad (weigerde in week 1). Ze legt 3454 namen op berkenbaststroken op tafel, die daarna op een brandstapel worden verbrand.',-1238,'h29'),
(6,'211 vertrekkers met Corran','211 vertrekkers met Corran (de Reckoner telt er 212) naar de zuidelijke uitlopers van Hoogvrouwe; Corran heft zijn arm naar de lucht. Aantal mag bij latere canon over het bergvolk worden bijgesteld.',-1238,'h30'),
(7,'Rook in jaar 6, camera\'s dood in jaar 9','In jaar 6 ziet Thalen rook in de vallei; de laatste landercamera\'s sterven in jaar 9 (lander zeven als laatste). De roest neemt eerst de camera van lander twee.',-1234,'h22/h30'),
(8,'Schriftverbod jaar 3, 5 tegen 2','Het schriftverbod gaat in jaar 3 (-1237) met 5 tegen 2 (Hesta onthoudt zich), nadat Venn een motie over onderwijs indient. Ysa verbrandt haar lijst en houdt haar potloodstompje.',-1237,'h31'),
(9,'Het lied "The ship went cold, the ship went mad"','Het lied ontstaat bij de visweren, met verzen over de Moeder en de piloot die bleef; Ysa zingt de leugen zuiver mee.',-1237,'h31'),
(10,'Eerste rode tomaat naar Sabe Mehr','De eerste rode tomaat (jaar 3) geeft Ysa aan Sabe Mehr.',-1237,'h31'),
(11,'Ysa\'s dood als vuur van drie nachten','Ysa sterft in -1209 (jaar 31); vanuit de baan zichtbaar als een vuur van drie nachten.',-1209,'h32'),
(12,'Thalens opname met Ysa\'s recorder','Thalen spreekt zijn stem in met Ysa\'s lab-recorder (de klik blijft erin). De labopname "The body is the price, Thalen. Everything else is bookkeeping." staat in de kluis; hij speelt ook "Fourth night before landing" af.',-1200,'h32'),
(13,'Thalens dood','Thalen sterft in -1198, op 74, dag 209 van zijn 75e levensjaar, in de stoel bij het raam: "Seated. Facing window."',-1198,'h33'),
(14,'"His was for later"','De scherf spreekt in 801 in Brakhaven met Ysa\'s stem tegen Liora: "Consent found. The Reckoner waits." Thalens stem is bewaard "for later".',801,'h33'),
(15,'Corran zocht een drempelfout, geen handtekening','Corran legde vanaf dag 1 het verband met Ysa\'s protocoltak, maar geloofde dat de tak vervroegd was door een drempel- of sensorfout (bloom, kernmetingen); hij zocht een getal, geen naam.',-1240,'h14/h16/h17'),
(16,'Hesta las de tak een jaar eerder; de Reckoner heeft een verborgen deur','Hesta las de reductietak ongeveer een jaar vóór Ysa. Haar bezoeken aan C-4-R dienden om uit te zoeken of de Reckoner een deur had die de raad niet kende. Die deur bestaat (inhoud open, haak naar de serie). Ze deelde dit nooit met Corran.',-1241,'h27'),
(17,'De Reckoner stopt met bedanken','Op Thalens verzoek ("Don\'t thank me for that") stopt de Reckoner met bedanken en registreert alleen: "Then I won\'t. I\'ll only record it."',-1239,'h22'),
(18,'"Good luck" op de ochtend van de stemming','Op de ochtend van de stemming opent Thalen de link naar Corran en zegt alleen "Luck. Corran. Good luck." Zijn derde keuze, en het dichtst dat hij bij ingrijpen kwam.',-1238,'h28'),
(19,'Corrans jaar van zoeken','Corran doorzocht een jaar lang sensorlogs, bloom en kernmetingen naar de drempel, vond niets en eiste pas toen de raadsbestanden (h23). Op de stemmingsdag ziet hij "the hand on the switch" (h29). Lijn h14 "Something\'s tripped it", h16, h17, h23, h29.',-1239,'h14/h23/h29')]
